package com.maiditquick.admin.security;
import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.http.HttpMethod; import org.springframework.http.HttpStatus; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.cors.*; import java.util.*;
@Configuration @EnableWebSecurity @EnableMethodSecurity
public class SecurityConfig {
  @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);}
  @Bean SecurityFilterChain security(HttpSecurity http, JwtAuthenticationFilter jwt, RateLimitFilter rateLimit, RestAuthenticationEntryPoint entryPoint) throws Exception { return http.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/v1/admin/auth/**","/api/v1/admin/login","/api/v1/admin/refresh-token","/api/v1/admin/forgot-password","/api/v1/admin/reset-password","/uploads/**","/actuator/health","/swagger-ui/**","/v3/api-docs/**").permitAll().requestMatchers(HttpMethod.GET,"/api/v1/admin/audit/**").hasAuthority("AUDIT_READ").anyRequest().authenticated()).exceptionHandling(e->e.authenticationEntryPoint(entryPoint)).addFilterBefore(rateLimit, UsernamePasswordAuthenticationFilter.class).addFilterBefore(jwt, UsernamePasswordAuthenticationFilter.class).build(); }
  @Bean CorsConfigurationSource corsConfigurationSource(@Value("${app.cors-origin}") String origin){ CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(List.of(origin));c.setAllowedMethods(List.of("GET","POST","PATCH","PUT","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type"));c.setAllowCredentials(true);var s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s; }
}
